//! The G-SP memo prototype (`benches/spike/memo.rs`) checked against cold evaluation, non-timing, class S only
//! (the L/XL fixtures are generated by the spike run):
//!
//! - the stamps the `Db` reports equal those `Q` observed, on a snapshot past two commits, for every dependency
//!   kind the connectivity families read (project row, rows, whole tables, ID and endpoint index keys);
//! - the dependency list is minimal (sorted, unique, no row reads of tables read whole);
//! - after a hit, an unrelated edit (a conductor colour), a move and a wire, the memoised `potential_partition`
//!   and `page_local_nets` equal the cold values, with `ew-memo`'s oracle on at every depth, and the engine
//!   counters show the expected path: a hit, a verification without re-execution, a re-execution that cuts off,
//!   a re-execution that changes the value;
//! - the durability of a commit follows its touched keys.

#[allow(dead_code)]
#[path = "../benches/spike/memo.rs"]
mod memo;

use std::num::NonZeroU32;

use ew_api::{Session, SessionOptions};
use ew_commands::commands::{Connect, EndpointParam, KindName, MoveReps, SetFields};
use ew_commands::testkit::seeded_ids;
use ew_derive::{DepKey, IxKey, PageLocalNets, PhysicalWiresOf, PotentialPartition, Q};
use ew_memo::{Durability, Oracle, Store};
use ew_model::{IndexName, Model};
use ew_schema::Record;
use ew_testkit::synth::{self, Handles, SizeClass};
use ew_units::Pt2;

use memo::{Memo, ModelDb, durability_of_keys, evaluate, minimal_deps, store_at};

fn session(model: &Model) -> Session {
    Session::new(
        model.clone(),
        SessionOptions {
            ids: Some(seeded_ids(1)),
            ..Default::default()
        },
    )
}

/// Advances `store` past the session's last commit and returns the database of the new snapshot.
fn advance(store: &mut Store<ModelDb>, session: &mut Session) -> ModelDb {
    let keys: Vec<_> = session
        .drain_changes()
        .into_iter()
        .flat_map(|c| c.touched_keys)
        .collect();
    let db = ModelDb::new(&session.world().model);
    store.advance(db.rev(), durability_of_keys(&keys));
    db
}

fn assert_partition_matches_cold(store: &mut Store<ModelDb>, db: &ModelDb) {
    let memoised = store.get::<Memo<PotentialPartition>>(db, &()).expect("no cycle");
    let cold = Q::new(db.model()).get::<PotentialPartition>(());
    assert_eq!(**memoised, *cold, "memoised potential_partition equals cold");
    assert!(store.take_mismatches().is_empty(), "the oracle found no mismatch");
}

#[test]
fn minimal_deps_drop_rows_of_tables_read_whole() {
    let g = synth::project(SizeClass::S, 1);
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    let (_, reads) = evaluate::<PotentialPartition>(&model, &());
    let deps = minimal_deps(&reads);
    assert!(!deps.is_empty() && deps.len() <= reads.len());
    let whole: Vec<_> = deps
        .iter()
        .filter_map(|d| match d {
            DepKey::Table(k) => Some(*k),
            _ => None,
        })
        .collect();
    assert!(
        deps.iter()
            .all(|d| !matches!(d, DepKey::Row((k, _)) if whole.contains(k)))
    );
    let mut sorted = deps.clone();
    sorted.sort();
    sorted.dedup();
    assert_eq!(sorted, deps, "sorted and unique");
}

/// A load representation moved by six by three grid steps.
fn move_cmd(handles: &Handles) -> MoveReps {
    MoveReps {
        reps: vec![handles.load_reps[0]],
        delta: Pt2::new(handles.grid.at(6).unwrap(), handles.grid.at(3).unwrap()),
        page: None,
    }
}

/// A wire between the first two free CPs of the first page that has two; with that page's index.
fn wire_cmd(handles: &Handles) -> (Connect, usize) {
    let p = (0..handles.pages.len())
        .find(|p| handles.free_cps[*p].len() >= 2)
        .expect("a page with two free CPs");
    let (a, b) = (handles.free_cps[p][0], handles.free_cps[p][1]);
    let cmd = Connect {
        a: EndpointParam::Cp {
            function: a.0,
            idx: a.1,
        },
        b: EndpointParam::Cp {
            function: b.0,
            idx: b.1,
        },
        page: Some(handles.pages[p]),
        route: Vec::new(),
        kind: Default::default(),
    };
    (cmd, p)
}

#[test]
fn stamps_of_the_db_are_the_stamps_q_observed() {
    let g = synth::project(SizeClass::S, 1);
    let handles = g.handles.clone();
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    // Two commits, so that the stamps differ between rows, tables and index keys.
    let mut s = session(&model);
    s.execute(&move_cmd(&handles)).expect("move accepted");
    let (wire, p) = wire_cmd(&handles);
    s.execute(&wire).expect("wire accepted");
    let model = s.world().model;
    let partition = Q::new(&model).get::<PotentialPartition>(());
    let mut reads = evaluate::<PotentialPartition>(&model, &()).1;
    reads.extend(evaluate::<PageLocalNets>(&model, &handles.pages[p]).1);
    for potential in partition.potentials.iter().take(20) {
        reads.extend(evaluate::<PhysicalWiresOf>(&model, &potential.id).1);
    }
    let db = ModelDb::new(&model);
    for (dep, observed) in &reads {
        assert_eq!(ew_memo::Db::changed_at(&db, dep).0, observed.0, "{dep:?}");
    }
    let has = |f: &dyn Fn(&DepKey) -> bool| reads.iter().any(|(d, _)| f(d));
    assert!(has(&|d| matches!(d, DepKey::Project)), "a project-row read");
    assert!(has(&|d| matches!(d, DepKey::Table(_))), "a whole-table read");
    assert!(has(&|d| matches!(d, DepKey::Row(_))), "a row read");
    assert!(
        has(&|d| matches!(d, DepKey::IndexKey(_, IxKey::Id(_)))),
        "an ID index-key read"
    );
    assert!(
        has(&|d| matches!(
            d,
            DepKey::IndexKey(IndexName::ConnectionsByEndpoint, IxKey::Endpoint(_))
        )),
        "an endpoint index-key read"
    );
    assert!(
        reads.iter().any(|(_, r)| r.0 > 0) && reads.iter().any(|(_, r)| r.0 == 0),
        "stamps of both the baseline and the commits"
    );
}

#[test]
fn memoised_connectivity_equals_cold_after_hit_unrelated_edit_move_and_wire() {
    let g = synth::project(SizeClass::S, 1);
    let handles = g.handles.clone();
    let conductor = g
        .records
        .iter()
        .find_map(|r| match r {
            Record::Conductor(c) => Some(c.id),
            _ => None,
        })
        .expect("the fixture has a conductor");
    let model = Model::from_records(g.project, g.records, g.lib).expect("valid model");
    let pages = handles.pages.len() as u64;
    let db0 = ModelDb::new(&model);
    let mut warm = store_at(&db0);
    warm.set_oracle(Oracle::Every);
    assert_partition_matches_cold(&mut warm, &db0);
    for page in &handles.pages {
        warm.get::<Memo<PageLocalNets>>(&db0, page).expect("no cycle");
    }
    // A second read at the same revision is a hit.
    assert_partition_matches_cold(&mut warm, &db0);
    let c = warm.commit_stats().family("potential_partition");
    assert_eq!((c.hits, c.re_executions), (1, 1), "{c:?}");

    // An unrelated edit: the conductor colour is not read by the partition, so one verification, no
    // re-execution, and the very same value.
    let mut fork = warm.fork();
    let before = fork.get::<Memo<PotentialPartition>>(&db0, &()).expect("no cycle");
    let mut s = session(&model);
    s.execute(&SetFields {
        kind: KindName::Conductor,
        targets: vec![conductor.cast()],
        path: "colour".into(),
        value: serde_json::json!(["BK"]),
    })
    .expect("conductor colour accepted");
    let db = advance(&mut fork, &mut s);
    let after = fork.get::<Memo<PotentialPartition>>(&db, &()).expect("no cycle");
    let c = fork.commit_stats().family("potential_partition");
    assert_eq!((c.verifications, c.re_executions), (1, 0), "{c:?}");
    assert!(
        std::sync::Arc::ptr_eq(&before, &after),
        "the memoised value is kept"
    );
    assert_partition_matches_cold(&mut fork, &db);

    // A move of a load representation: the partition re-executes and cuts off; one page's local nets
    // re-execute and cut off, the other pages are verified.
    let mut fork = warm.fork();
    let mut s = session(&model);
    s.execute(&move_cmd(&handles)).expect("move accepted");
    let db1 = advance(&mut fork, &mut s);
    assert_partition_matches_cold(&mut fork, &db1);
    let c = fork.commit_stats().family("potential_partition");
    assert_eq!((c.re_executions, c.cut_offs), (1, 1), "{c:?}");
    for page in &handles.pages {
        let m = fork.get::<Memo<PageLocalNets>>(&db1, page).expect("no cycle");
        assert_eq!(**m, *Q::new(db1.model()).get::<PageLocalNets>(*page));
    }
    let c = fork.commit_stats().family("page_local_nets");
    assert_eq!(
        (c.re_executions, c.cut_offs, c.verifications),
        (1, 1, pages - 1),
        "{c:?}"
    );
    assert!(fork.take_mismatches().is_empty());

    // A new wire: the partition and the page's local nets re-execute and change.
    let mut fork = warm.fork();
    fork.set_oracle(Oracle::OneIn(NonZeroU32::new(1).unwrap()));
    let mut s = session(&model);
    let (wire, p) = wire_cmd(&handles);
    s.execute(&wire).expect("wire accepted");
    let db2 = advance(&mut fork, &mut s);
    assert_partition_matches_cold(&mut fork, &db2);
    let c = fork.commit_stats().family("potential_partition");
    assert_eq!((c.re_executions, c.cut_offs), (1, 0), "{c:?}");
    let nets = fork
        .get::<Memo<PageLocalNets>>(&db2, &handles.pages[p])
        .expect("no cycle");
    assert_eq!(
        **nets,
        *Q::new(db2.model()).get::<PageLocalNets>(handles.pages[p])
    );
    let c = fork.commit_stats().family("page_local_nets");
    assert_eq!((c.re_executions, c.cut_offs), (1, 0), "{c:?}");
    assert!(fork.take_mismatches().is_empty());
}

#[test]
fn durability_of_commits() {
    use ew_schema::Kind;
    let id = ew_ids::Id::<()>::from_uuid(ew_ids::Uuid::from_u128(1));
    assert_eq!(durability_of_keys(&[]), Durability::Drawing);
    assert_eq!(durability_of_keys(&[(Kind::Connection, id)]), Durability::Drawing);
    assert_eq!(
        durability_of_keys(&[(Kind::Connection, id), (Kind::Project, id)]),
        Durability::Settings
    );
    assert_eq!(
        durability_of_keys(&[(Kind::Symbol, id), (Kind::Project, id)]),
        Durability::Library
    );
    assert_eq!(memo::durability_of(&DepKey::Project), Durability::Settings);
    assert_eq!(
        memo::durability_of(&DepKey::Table(Kind::Fndef)),
        Durability::Library
    );
}
